'use strict';
window.IlkerAccess=(()=>{
 let api,fail,signedOut,user,activeDialog,auditOffset=0;
 const $=s=>document.querySelector(s);
 const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
 const staticText=(tag,key,cls)=>{const e=el(tag,key,cls);window.IlkerAdminI18n?.bind(e,key);return e;};
 const role=value=>value==='owner'?'Владелец':'Ресепшен';
 function button(text,handler,primary=false){const b=staticText('button',text,primary?'button primary':'text-button');b.type='button';b.addEventListener('click',async()=>{b.disabled=true;try{await handler();}catch(e){fail(e);}finally{b.disabled=false;}});return b;}
 function field(text,type,value=''){const label=staticText('label',text),input=el('input');input.type=type;input.value=value;input.setAttribute('aria-label',text);window.IlkerAdminI18n?.bind(input,text,'aria-label');if(type==='password'){input.maxLength=200;input.autocomplete='new-password';}label.append(input);return {label,input};}
 function modal(title){if(activeDialog)activeDialog.close();const d=el('dialog',undefined,'reception-dialog'),form=el('form'),error=el('p',undefined,'reception-error');error.setAttribute('role','alert');form.append(staticText('h2',title),error);d.append(window.IlkerAdminI18n?.makeSwitcher()||el('span'),form);d.addEventListener('close',()=>{d.remove();if(activeDialog===d)activeDialog=null;});document.body.append(d);activeDialog=d;d.showModal();return {d,form,error};}
 function submit(view,fields,label,run){const save=staticText('button',label,'button primary');save.type='submit';view.form.append(fields,save,button('Закрыть',()=>view.d.close()));view.form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;fields.disabled=true;view.error.textContent='';try{await run();view.d.close();}catch(error){view.error.textContent=error.status?error.message:'Ответ не получен. Проверьте состояние перед повтором.';if(error.status===401){view.d.close();signedOut();}}finally{save.disabled=false;fields.disabled=false;}});}
 function proofField(){const proof=field('Ваш текущий пароль','password');proof.input.required=true;proof.input.autocomplete='current-password';return proof;}
 async function password(){const view=modal('Смена пароля'),fields=el('fieldset',undefined,'reception-fields'),current=proofField(),next=field('Новый пароль','password'),repeat=field('Повторите новый пароль','password');next.input.minLength=repeat.input.minLength=12;next.input.required=repeat.input.required=true;fields.append(current.label,next.label,repeat.label,el('p','После смены пароля все ваши устройства выйдут из аккаунта. Push потребуется включить снова.','small-note'));
  submit(view,fields,'Изменить пароль',async()=>{if(next.input.value!==repeat.input.value)throw Object.assign(new Error('Пароли не совпадают.'),{status:400});await api('/api/admin/account/password',{currentPassword:current.input.value,newPassword:next.input.value});signedOut();});
 }
 async function revoke(device=null){const view=modal(device?'Завершить сессию':'Выйти на всех устройствах'),fields=el('fieldset',undefined,'reception-fields'),proof=proofField();fields.append(proof.label,el('p',device?'Выбранное устройство потребуется авторизовать снова.':'Все сессии будут завершены; Push отключится до повторного включения.','small-note'));submit(view,fields,'Подтвердить',async()=>{const data=await api('/api/admin/account/revoke',{id:device?.id,all:!device,currentPassword:proof.input.value});if(data.signInRequired)signedOut();else await render();});}
 async function editUser(row=null){const view=modal(row?'Доступ сотрудника':'Новый сотрудник'),fields=el('fieldset',undefined,'reception-fields'),name=field('Имя сотрудника','text',row?.display_name),login=field('Логин','text',row?.login),next=field(row?'Новый пароль сотрудника (если нужно)':'Пароль сотрудника','password'),proof=proofField();login.input.required=true;login.input.autocomplete='off';login.input.pattern='[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}';login.input.maxLength=40;name.input.maxLength=80;next.input.minLength=12;next.input.required=!row;
  const roleLabel=staticText('label','Роль'),select=el('select');select.setAttribute('aria-label','Роль');window.IlkerAdminI18n?.bind(select,'Роль','aria-label');for(const value of ['reception','owner']){const option=staticText('option',role(value));option.value=value;select.append(option);}select.value=row?.role||'reception';roleLabel.append(select);
  const active=field('Доступ разрешён','checkbox');active.input.checked=row?Boolean(row.active):true;fields.append(name.label,login.label,roleLabel,active.label,next.label,proof.label,el('p','При отключении, смене роли или пароля сессии и Push сотрудника отзываются.','small-note'));
  submit(view,fields,'Сохранить доступ',async()=>{await api('/api/admin/users',{id:row?.id,revision:row?.revision,login:login.input.value,displayName:name.input.value,role:select.value,active:active.input.checked,newPassword:next.input.value||undefined,currentPassword:proof.input.value});await render();});
 }
 async function audit(){const view=modal('Журнал действий'),data=await api('/api/admin/audit?offset='+auditOffset);for(const row of data.rows){const card=el('article',undefined,'appointment');card.append(el('strong',row.action),el('p',`${row.created_at} · ${row.actor}`),el('p',`${row.entity_type} · ${row.entity_id}`),el('pre',row.details_json,'access-details'));view.form.append(card);}const tools=el('div',undefined,'action-row');const prev=button('Назад',()=>{auditOffset=Math.max(0,auditOffset-50);return audit();}),next=button('Следующие 50',()=>{auditOffset+=50;return audit();});prev.disabled=auditOffset===0;next.disabled=data.rows.length<50;tools.append(prev,next,button('Закрыть',()=>view.d.close()));view.form.append(tools);}
 async function render(){const root=$('#settings-view');const [account,devices]=await Promise.all([api('/api/admin/account'),api('/api/admin/account/sessions')]);user=account.user;root.replaceChildren(staticText('h2','Доступ и безопасность'));const card=el('article',undefined,'appointment');card.append(el('strong',user.display_name||user.login),staticText('p',role(user.role)),button('Изменить пароль',password),button('Выйти на всех устройствах',()=>revoke()));root.append(card);
  const settings=el('form',undefined,'appointment'),privacy=field('Скрывать дату и время в Push','checkbox'),languageLabel=staticText('label','Язык Push-уведомлений'),language=el('select');privacy.input.checked=Boolean(user.push_private);language.setAttribute('aria-label','Язык Push-уведомлений');window.IlkerAdminI18n?.bind(language,'Язык Push-уведомлений','aria-label');for(const [value,text]of [['ru','Русский'],['az','Azərbaycan'],['en','English']]){const option=el('option',text);option.value=value;language.append(option);}language.value=user.language;languageLabel.append(language);const save=staticText('button','Сохранить уведомления','button primary'),message=el('p',undefined,'small-note');message.setAttribute('role','status');settings.append(languageLabel,privacy.label,save,message);settings.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;try{const result=await api('/api/admin/account/preferences',{language:language.value,pushPrivate:privacy.input.checked});user=result.user;message.textContent='Настройки сохранены.';}catch(error){fail(error);}finally{save.disabled=false;}});root.append(settings,staticText('h3','Ваши устройства'));
  for(const device of devices.rows){const row=el('article',undefined,'appointment');row.append(el('strong',device.device+(device.current?' · это устройство':'')),el('p','Последняя активность: '+new Date(device.last_seen).toLocaleString('ru-RU')),button('Завершить сессию',()=>revoke(device)));root.append(row);}
  if(user.role==='owner'){const users=await api('/api/admin/users');root.append(staticText('h3','Сотрудники'),button('+ Добавить сотрудника',()=>editUser(),true));for(const employee of users.rows){const row=el('article',undefined,'appointment');row.append(el('strong',employee.display_name||employee.login),el('p',`${role(employee.role)} · ${employee.active?'Доступ разрешён':'Отключён'}`),button('Настроить доступ',()=>editUser(employee)));root.append(row);}root.append(button('Журнал действий',()=>{auditOffset=0;return audit();}));}
 }
 async function init(request,onError,onLogout){api=request;fail=onError;signedOut=onLogout;user=(await api('/api/admin/account')).user;$('#tab-settings').hidden=false;for(const id of ['services','masters','rooms','revenue'])$('#tab-'+id).hidden=user.role!=='owner';}
 function clear(){activeDialog?.close();$('#settings-view')?.replaceChildren();user=null;}
 return {init,render,clear,get owner(){return user?.role==='owner';}};
})();
